<?php if($adminSection==='settings'): ?>
<div class="wg-box"><form class="admin-form" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="settings"><div class="row"><?php foreach($settingFields as $k): $v=setting($k); ?><div class="col-md-6 field"><label for="<?= $k ?>"><?= h(ucwords(str_replace('_',' ',$k))) ?></label><?php if(in_array($k,['payment_cod','payment_bank_transfer','analytics_enabled'])): ?><input type="checkbox" id="<?= $k ?>" name="<?= $k ?>" <?= $v==='1'?'checked':'' ?>><?php elseif(in_array($k,['address','bank_instructions','meta_description'])): ?><textarea id="<?= $k ?>" name="<?= $k ?>"><?= h($v) ?></textarea><?php else: ?><input id="<?= $k ?>" name="<?= $k ?>" value="<?= h($v) ?>"><?php endif; ?><?php if($k==='home_sections'): ?><p class="help">Comma-separated order: featured,new,sale,bestsellers,blog. Omit a section to hide it.</p><?php endif; ?></div><?php endforeach; foreach(['logo','favicon'] as $k): ?><div class="col-md-6 field"><label for="<?= $k ?>"><?= ucfirst($k) ?></label><img class="image-preview" src="<?= h(url(setting($k))) ?>" alt="Current <?= $k ?>"><input type="file" name="<?= $k ?>" id="<?= $k ?>" accept="image/jpeg,image/png,image/gif,image/webp"></div><?php endforeach; ?></div><button class="tf-button">Save settings</button></form></div>
<?php elseif($adminSection==='orders'&&$id): $o=row('SELECT * FROM orders WHERE id=?',[$id]);if(!$o): ?><p>Order not found.</p><?php else: ?><div class="report-grid"><div class="wg-box"><h4>Order #<?= $o['id'] ?></h4><p><?= h($o['created_at']) ?><?= $o['source_id']?' · Historical import':'' ?></p><h5><?= h($o['customer_name']) ?></h5><p><?= h($o['email'].' / '.$o['phone']) ?></p><p><?= nl2br(h($o['address'])) ?><br><?= h($o['city'].' '.$o['country']) ?></p><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM order_items WHERE order_id=?',[$id]) as $i): ?><tr><td><?= h($i['name']) ?></td><td><?= $i['quantity'] ?></td><td><?= h($i['unit_price']) ?></td><td><?= h($i['total']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php foreach(['subtotal','shipping','tax','total'] as $k): ?><p><?= ucfirst($k) ?>: <?= h($o['currency'].' '.number_format($o[$k],2)) ?></p><?php endforeach; ?><p>Payment method: <?= h($o['payment_method']) ?></p></div><div class="wg-box"><h5>Update order</h5><form method="post" class="admin-form"><?= csrf_field() ?><input type="hidden" name="action" value="order"><input type="hidden" name="id" value="<?= $id ?>"><label for="status">Status</label><select id="status" name="status"><?php foreach(['pending','confirmed','processing','shipped','delivered','cancelled','refunded'] as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><label for="payment_status">Payment state</label><select id="payment_status" name="payment_status"><?php foreach(['unpaid','paid','refunded'] as $s): ?><option <?= $o['payment_status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><label for="notes">Order notes</label><textarea id="notes" name="notes"><?= h($o['notes']) ?></textarea><label for="note">Status update note</label><textarea id="note" name="note"></textarea><button class="tf-button">Update order</button><p class="help mt-3">Mark paid only after verifying receipt. Refunded status records an externally processed refund; it does not send money. Cancelled native orders restore managed stock once.</p></form><h5>History</h5><?php foreach(rows('SELECT * FROM order_history WHERE order_id=? ORDER BY id DESC',[$id]) as $r): ?><p><?= h($r['created_at'].' · '.$r['status'].' · '.$r['note']) ?></p><?php endforeach; ?></div></div><?php endif; ?>
<?php elseif($adminSection==='customers'&&$id): $u=row('SELECT id,name,email,phone,active,created_at,last_login FROM users WHERE id=? AND role="customer"',[$id]);if(!$u): ?><p>Customer not found.</p><?php else: ?><div class="report-grid"><div class="wg-box"><h4><?= h($u['name']) ?></h4><p><?= h($u['email']) ?></p><p>Registered <?= h($u['created_at']) ?></p><p>Last login <?= h($u['last_login']??'Never') ?></p><form method="post" class="admin-form"><?= csrf_field() ?><input type="hidden" name="action" value="customer"><input type="hidden" name="id" value="<?= $id ?>"><label for="name">Name</label><input name="name" id="name" required value="<?= h($u['name']) ?>"><label for="phone">Phone</label><input id="phone" name="phone" value="<?= h($u['phone']) ?>"><label><input name="active" type="checkbox" <?= $u['active']?'checked':'' ?>> Account active</label><button class="tf-button mt-3">Save customer</button></form><h5>Addresses</h5><?php foreach(rows('SELECT * FROM addresses WHERE user_id=?',[$id]) as $a): ?><p><?= h($a['name'].' · '.$a['address'].' · '.$a['city'].' · '.$a['country']) ?></p><?php endforeach; ?></div><div class="wg-box"><h5>Order history</h5><?php $summary=row('SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN payment_status="paid" AND status NOT IN ("cancelled","refunded") THEN total ELSE 0 END),0) spend FROM orders WHERE user_id=?',[$id]); ?><p><?= $summary['orders'] ?> orders · <?= h(money($summary['spend'])) ?> lifetime paid spend</p><div class="table-scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 100',[$id]) as $o): ?><tr><td><a href="<?= url('admin/orders.php?id='.$o['id']) ?>">#<?= $o['id'] ?></a></td><td><?= h($o['currency'].' '.$o['total']) ?></td><td><?= h($o['status']) ?></td><td><?= h($o['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php endif; ?>
<?php elseif($adminSection==='admins'): $editing=$id?row('SELECT id,name,email,phone,active,created_at,last_login FROM users WHERE id=? AND role="admin"',[$id]):null; if($id&&!$editing): ?><p>Administrator account not found.</p><?php else: $q=trim($_GET['q']??'');$adminList=rows('SELECT id,name,email,phone,active,created_at,last_login FROM users WHERE role="admin" AND (name LIKE ? OR email LIKE ? OR phone LIKE ?) ORDER BY active DESC,name ASC',array_fill(0,3,'%'.$q.'%')); ?><div class="report-grid"><div class="wg-box"><h4><?= $editing?'Edit administrator':'Add administrator' ?></h4><p class="help">Set a new password here when creating or resetting an account. Saved passwords cannot be viewed because they are stored securely.</p><form method="post" class="admin-form" autocomplete="off"><?= csrf_field() ?><input type="hidden" name="action" value="administrator"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><label for="admin_name">Full name</label><input name="name" id="admin_name" required value="<?= h($editing['name']??'') ?>"><label for="admin_email">Email address</label><input type="email" name="email" id="admin_email" required value="<?= h($editing['email']??'') ?>"><label for="admin_phone">Phone</label><input name="phone" id="admin_phone" value="<?= h($editing['phone']??'') ?>"><label for="admin_password"><?= $editing?'Set new password (leave blank to keep current password)':'Password' ?></label><input type="password" name="password" id="admin_password" <?= $editing?'':'required' ?> minlength="10" autocomplete="new-password"><button type="button" class="tq-table-reset tq-password-toggle" data-password-toggle="admin_password">Show password</button><p class="help">Use at least 10 characters. Resetting a password signs the other administrator out of their existing sessions.</p><label><input name="active" type="checkbox" <?= (!$editing||$editing['active'])?'checked':'' ?>> Account active</label><button class="tf-button mt-3"><?= $editing?'Save administrator':'Create administrator' ?></button><?php if($editing): ?><a class="tf-button style-3 mt-3" href="<?= url('admin/admins.php') ?>">Add another</a><?php endif; ?></form></div><div class="wg-box"><form class="tq-table-tools" method="get"><input name="q" placeholder="Search administrators" value="<?= h($q) ?>"><button class="tf-button">Search</button><?php if($q!==''): ?><a class="tq-table-reset" href="<?= url('admin/admins.php') ?>">Clear</a><?php endif; ?><span class="tq-table-count"><?= count($adminList) ?> accounts</span></form><div class="table-scroll"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody><?php foreach($adminList as $admin): ?><tr><td><strong><?= h($admin['name']) ?></strong><?= (int)$admin['id']===(int)user()['id']?' <small>(You)</small>':'' ?></td><td><?= h($admin['email']) ?></td><td><?= h($admin['phone']?:'—') ?></td><td><?= $admin['active']?'Active':'Disabled' ?></td><td><?= h($admin['last_login']??'Never') ?></td><td><a class="tf-button style-3" href="<?= url('admin/admins.php?id='.$admin['id']) ?>">Manage</a></td></tr><?php endforeach; if(!$adminList): ?><tr><td colspan="6" class="tq-grid-empty">No administrator accounts match your search.</td></tr><?php endif; ?></tbody></table></div></div></div><script>document.querySelectorAll('[data-password-toggle]').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.getAttribute('data-password-toggle'));if(!input)return;var show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide password':'Show password';});});</script><?php endif; ?>
<?php else: $page=max(1,(int)($_GET['page']??1));$q=trim($_GET['q']??'');$where='1=1';$args=[];
if($adminSection==='orders'){$table='orders';$where='(customer_name LIKE ? OR email LIKE ? OR CAST(id AS CHAR)=?)';$args=['%'.$q.'%','%'.$q.'%',$q];if(!empty($_GET['status'])){$where.=' AND status=?';$args[]=$_GET['status'];}foreach(['from'=>'>=','to'=>'<='] as $k=>$op)if(!empty($_GET[$k])&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET[$k])){$where.=" AND created_at $op ?";$args[]=$_GET[$k].($k==='to'?' 23:59:59':' 00:00:00');}$cols=['id','customer_name','email','total','currency','status','payment_status','created_at'];}
elseif($adminSection==='customers'){$table='users';$where='role="customer" AND (name LIKE ? OR email LIKE ? OR phone LIKE ?)';$args=array_fill(0,3,'%'.$q.'%');$cols=['id','name','email','phone','active','created_at','last_login'];}
elseif($adminSection==='audit'){$table='audit_logs';$cols=['id','admin_id','action','resource','resource_id','context','created_at'];if($q!==''){$where='(action LIKE ? OR resource LIKE ? OR context LIKE ? OR CAST(resource_id AS CHAR)=?)';$args=['%'.$q.'%','%'.$q.'%','%'.$q.'%',$q];}}
else{$table='contact_messages';$cols=['id','name','email','subject','message','created_at'];if($q!==''){$where='(name LIKE ? OR email LIKE ? OR subject LIKE ? OR message LIKE ?)';$args=array_fill(0,4,'%'.$q.'%');}}
$total=(int)scalar("SELECT COUNT(*) FROM `$table` WHERE $where",$args);$list=rows('SELECT '.implode(',',$cols)." FROM `$table` WHERE $where ORDER BY id DESC LIMIT 25 OFFSET ".(($page-1)*25),$args);
?><form class="admin-toolbar"><input name="q" placeholder="Search customers or orders" value="<?= h($q) ?>"><?php if($adminSection==='orders'): ?><select name="status"><option value="">All states</option><?php foreach(['pending','confirmed','processing','shipped','delivered','cancelled','refunded'] as $s): ?><option <?= ($_GET['status']??'')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><input type="date" name="from" aria-label="From date" value="<?= h($_GET['from']??'') ?>"><input type="date" name="to" aria-label="To date" value="<?= h($_GET['to']??'') ?>"><?php endif; ?><button class="tf-button">Filter</button><span><?= $total ?> records</span></form><div class="wg-box"><div class="table-scroll"><table class="admin-table"><thead><tr><?php foreach($cols as $k): ?><th><?= h(ucwords(str_replace('_',' ',$k))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($list as $r): ?><tr><?php foreach($r as $k=>$v): ?><td><?php if($k==='id'&&in_array($adminSection,['orders','customers'])): ?><a href="?id=<?= $r['id'] ?>">#<?= $r['id'] ?></a><?php else: ?><?= nl2br(h($v)) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></div><div class="admin-toolbar mt-4"><?php if($page>1): ?><a class="tf-button style-3" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif; ?>Page <?= $page ?> of <?= max(1,ceil($total/25)) ?><?php if($page*25<$total): ?><a class="tf-button style-3" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div><?php endif; ?>
